CREATE TABLE iam_attachments (
	id VARCHAR(64) NOT NULL, 
	policy_id VARCHAR(255) NOT NULL, 
	principal_id VARCHAR(64) NOT NULL, 
	scope TEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT iam_attachments_once UNIQUE (policy_id, principal_id, scope), 
	FOREIGN KEY(policy_id) REFERENCES iam_policies (id), 
	FOREIGN KEY(principal_id) REFERENCES iam_principals (id)
);
