	group_id VARCHAR(64) NOT NULL, 
	member_id VARCHAR(64) NOT NULL, 
	PRIMARY KEY (group_id, member_id), 
	FOREIGN KEY(group_id) REFERENCES iam_principals (id) ON DELETE CASCADE, 
