	key_id VARCHAR(32) NOT NULL, 
	principal_id VARCHAR(64) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	secret_hash VARCHAR(64) NOT NULL, 
	description TEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	expires_at DATETIME, 
